### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    // Caso N = 1
    if (n == 1) {
        printf("1\n");
        return 0;
    }

    // Caso N = 2: média de dois números distintos nunca pode ser igual a um deles
    if (n == 2) {
        printf("-1\n");
        return 0;
    }

    long long v[45];

    if (n % 2 != 0) {
        // N ímpar: progressão aritmética simples de 1 a N
        for (int i = 0; i < n; i++) {
            v[i] = i + 1;
        }
    } else {
        // N par (N >= 4): primeiros N - 1 inteiros consecutivos e o último ajustado
        for (int i = 0; i < n - 1; i++) {
            v[i] = i + 1;
        }
        v[n - 1] = (long long)n * (n - 1) / 2;
    }

    // K deve ser maior que o maior elemento de v para garantir unicidade
    long long k = 1000;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            long long val = k * v[i] + v[j];
            printf("%lld%c", val, (j == n - 1) ? '\n' : ' ');
        }
    }

    return 0;
}
```

